import pandas as pd,numpy as np,json
hist=pd.read_csv('/app/target_history.csv');latest=hist[hist.year==2028];rows=[];fits={}
for name,g in hist.groupby('furniture_name'):
 X=pd.get_dummies(g.locality,dtype=float);cities=list(X.columns);X['t']=g.year-2027;b=np.linalg.lstsq(X.to_numpy(),np.log(g.items_sold),rcond=None)[0];slope=float(b[-1]);fits[name]={'annual_log_growth':slope,'baselines':{}}
 for j,city in enumerate(cities):
  fitted=float(np.exp(b[j]+slope));actual=float(latest[(latest.locality==city)&(latest.furniture_name==name)].items_sold.iloc[0]);baseline=.6*fitted+.4*actual;fits[name]['baselines'][city]=baseline
  for year in range(2029,2034):
   h=year-2028;factor=np.exp(slope*sum(.9**k for k in range(h)));rows.append({'locality':city,'furniture_name':name,'year':year,'items_sold':int(round(baseline*factor))})
